import type { SupabaseClient } from "@supabase/supabase-js";

/** Staged object names are generated by the upload route; reject traversal and foreign sessions. */
export function isOwnedStagedPath(path: string, ownerId: string, uploadId: string, kind: "image" | "document") {
  if (!/^[a-zA-Z0-9-]{12,100}$/.test(uploadId) || !ownerId) return false;
  const prefix = `${ownerId}/profile-uploads/${uploadId}/${kind}-`;
  if (!path.startsWith(prefix)) return false;
  return /^[a-zA-Z0-9-]+\.(jpg|jpeg|png|webp|pdf)$/i.test(path.slice(prefix.length));
}

/** Tombstone registered per-file paths before Storage removal. Unknown/consumed files are retained. */
export async function removeUnreferencedStagedUploads(
  supabase: SupabaseClient,
  ownerId: string,
  uploadId: string,
  mediaCandidates: string[],
  documentCandidates: string[]
) {
  const media = [...new Set(mediaCandidates.filter((path) => isOwnedStagedPath(path, ownerId, uploadId, "image")))];
  const documents = [...new Set(documentCandidates.filter((path) => isOwnedStagedPath(path, ownerId, uploadId, "document")))];
  if (!media.length && !documents.length) return true;
  try {
    const result = await supabase.rpc("cleanup_staged_instrument_uploads", {
      p_owner_id: ownerId, p_upload_id: uploadId, p_media_paths: media, p_document_paths: documents
    });
    if (result.error || result.data?.ok !== true ||
        !Array.isArray(result.data.mediaPaths) || !Array.isArray(result.data.documentPaths)) return false;
    const removeMedia = result.data.mediaPaths as unknown[];
    const removeDocuments = result.data.documentPaths as unknown[];
    // The server may authorize only the caller's requested, owned paths. Never
    // broaden Storage removal if an unexpected/malformed result is received.
    if (removeMedia.some((path) => typeof path !== "string" || !media.includes(path)) ||
        removeDocuments.some((path) => typeof path !== "string" || !documents.includes(path))) return false;
    const outcomes = await Promise.all([
      removeMedia.length ? supabase.storage.from("instrument-media").remove(removeMedia as string[]) : { error: null },
      removeDocuments.length ? supabase.storage.from("instrument-documents").remove(removeDocuments as string[]) : { error: null }
    ]);
    // A failed/unknown deletion keeps its tombstone. Cleanup can retry deletion;
    // create can never bind that path again, even if the object still exists.
    return outcomes.every((result) => !result.error);
  } catch {
    return false;
  }
}

